          <label class="choice"><input type="checkbox" name="q1" value="spanish"><span>Spanish</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="javascript"><span>JavaScript</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="ruby"><span>Ruby</span></label>
        </div>
      </div>

      <div class="form-field">
        <h2>2. Which languages are commonly used for web development?</h2>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q2" value="css"><span>CSS</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="sql"><span>SQL</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="ruby"><span>Ruby</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="asm"><span>Assembly</span></label>
        </div>
      </div>

      <div class="form-field">
        <h2>3. Which of these are examples of markup or query languages?</h2>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q3" value="html"><span>HTML</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="markdown"><span>Markdown</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="sql"><span>SQL</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="go"><span>Go</span></label>
        </div>
      </div>

      <div class="actions">
        <button type="submit">Submit Quiz</button>
        <div class="result" id="result" aria-live="polite"></div>
      </div>
    </form>
  </main>

  <script>
    const quizForm = document.getElementById('quiz-form');
    const result = document.getElementById('result');

    const answers = {
      q1: ['python', 'javascript', 'ruby'],
      q2: ['css', 'sql', 'ruby'],
      q3: ['html', 'sql', 'markdown']
    };

    function getSelectedValues(name) {
      return [...document.querySelectorAll(`input[name="${name}"]:checked`)].map(input => input.value).sort();
    }

    function arraysEqual(left, right) {
      if (left.length !== right.length) return false;
      return left.every((value, index) => value === right[index]);
    }

    quizForm.addEventListener('submit', (event) => {
      event.preventDefault();

      let score = 0;
      for (const [question, expected] of Object.entries(answers)) {
        const selected = getSelectedValues(question);
        if (arraysEqual(selected, [...expected].sort())) {
          score += 1;
        }
      }

      result.innerHTML = `<strong>${score}/3</strong> correct.`;
    });
  </script>
